namespace sv_5939d74dc7294adebe9c204e28e21911.Services;

/// <summary>
/// Scoped service (one per circuit) that holds the currently selected warehouse
/// and notifies subscribers when the selection changes.
/// </summary>
public class WarehouseStateService
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId => _currentWarehouseId;

    public event Func<Task>? OnWarehouseChanged;

    public static IReadOnlyList<(string Id, string Name)> AvailableWarehouses { get; } =
    [
        ("WH-001", "Warehouse A — Downtown"),
        ("WH-002", "Warehouse B — Airport"),
        ("WH-003", "Warehouse C — Harbor"),
    ];

    public async Task SetWarehouseAsync(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;

        _currentWarehouseId = warehouseId;

        if (OnWarehouseChanged is not null)
        {
            await OnWarehouseChanged.Invoke();
        }
    }
}

namespace sv_5939d74dc7294adebe9c204e28e21911.Services;

/// <summary>
/// Scoped service (one per circuit) that polls for low-stock alerts
/// and notifies all subscribed components when new data arrives.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int LatestLowStockCount { get; private set; }

    /// <summary>
    /// Fired when polling retrieves new alert data. All subscribed components should refresh.
    /// </summary>
    public event Func<Task>? OnAlertDataChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnWarehouseChanged += HandleWarehouseChangedAsync;
    }

    /// <summary>
    /// Simulates a database query returning the count of items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate async DB call with random result
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Starts polling if not already running. Reference-counted so multiple components
    /// can call Start/Stop independently.
    /// </summary>
    public void StartPolling()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            _cts = new CancellationTokenSource();
            _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            _ = PollLoopAsync(_cts.Token);
        }
    }

    /// <summary>
    /// Stops polling when the last subscriber unsubscribes.
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            _cts?.Cancel();
            _timer?.Dispose();
            _timer = null;
        }
    }

    /// <summary>
    /// Forces an immediate refresh (e.g., after warehouse switch) and notifies subscribers.
    /// </summary>
    public async Task RefreshNowAsync()
    {
        LatestLowStockCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        if (OnAlertDataChanged is not null)
        {
            await OnAlertDataChanged.Invoke();
        }
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fire immediately on start
        await RefreshNowAsync();

        while (!ct.IsCancellationRequested)
        {
            try
            {
                if (_timer is null || !await _timer.WaitForNextTickAsync(ct))
                    break;

                await RefreshNowAsync();
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private async Task HandleWarehouseChangedAsync()
    {
        // When the warehouse changes, immediately refresh alerts for the new warehouse
        if (_subscriberCount > 0)
        {
            await RefreshNowAsync();
        }
    }

    public void Dispose()
    {
        _warehouseState.OnWarehouseChanged -= HandleWarehouseChangedAsync;
        _cts?.Cancel();
        _timer?.Dispose();
    }
}

