@page "/dashboard"
@rendermode InteractiveServer
@using sv_5939d74dc7294adebe9c204e28e21911.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="lead">
    Currently viewing: <strong>@CurrentWarehouseName</strong>
</p>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card @CardBorderClass">
            <div class="card-body text-center">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="display-3 @TextClass">@AlertService.LatestLowStockCount</p>
                <p class="text-muted">items below minimum level</p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Polling Status</h5>
                <p class="display-6">🟢 Active</p>
                <p class="text-muted">Refreshing every 10 seconds</p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Warehouse ID</h5>
                <p class="display-6 font-monospace">@WarehouseState.CurrentWarehouseId</p>
                <p class="text-muted">Select a different site above</p>
            </div>
        </div>
    </div>
</div>

@code {
    private string CurrentWarehouseName =>
        WarehouseStateService.AvailableWarehouses
            .FirstOrDefault(w => w.Id == WarehouseState.CurrentWarehouseId).Name
        ?? "Unknown";

    private string CardBorderClass => AlertService.LatestLowStockCount > 5
        ? "border-danger" : "border-warning";

    private string TextClass => AlertService.LatestLowStockCount > 5
        ? "text-danger" : "text-warning";

    protected override void OnInitialized()
    {
        // Subscribe to both warehouse changes and alert updates
        WarehouseState.OnWarehouseChanged += HandleStateChangedAsync;
        AlertService.OnAlertDataChanged += HandleStateChangedAsync;

        // Start polling — this page owns the polling lifecycle
        AlertService.StartPolling();
    }

    private Task HandleStateChangedAsync()
    {
        InvokeAsync(StateHasChanged);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= HandleStateChangedAsync;
        AlertService.OnAlertDataChanged -= HandleStateChangedAsync;

        // Stop polling when leaving the dashboard
        AlertService.StopPolling();
    }
}

